  const request = async (path: string, body?: unknown, method = body === undefined ? "GET" : "POST", headers: Record<string, string> = {}) => fetch(`http://127.0.0.1:${app.server.port}${path}`, { method, headers: { authorization: "[REDACTED]", "content-type": "application/json", ...headers }, body: body === undefined ? undefined : JSON.stringify(body) })
