import { afterEach, expect, test } from "bun:test"
import { mkdirSync, mkdtempSync, readFileSync, rmSync, writeFileSync } from "node:fs"
import { join } from "node:path"
import { tmpdir } from "node:os"
import { SoulStore } from "../src/store"
import { OpenCodeAdapter } from "../src/adapter"
import { startServer } from "../src/server"

const fixtures: { root: string; store: SoulStore; app: ReturnType<typeof startServer> }[] = []
function fixture() {
  const root = mkdtempSync(join(tmpdir(), "xingyao-workspace-api-")), project = join(root, "project"), host = join(root, "host")
  mkdirSync(project); mkdirSync(host)
  const store = new SoulStore(join(host, "soul.db"))
  const app = startServer({ store, token: "[REDACTED]", adapter: new OpenCodeAdapter({ baseURL: "http://127.0.0.1:1" }), vaultDir: join(root, "vault"), workspaceDirectory: project })
  fixtures.push({ root, store, app })
  const request = (path: string, input?: unknown, method = input === undefined ? "GET" : "POST", headers: Record<string, string> = {}) => fetch(`http://127.0.0.1:${app.server.port}/api${path}`, { method, headers: { authorization: "[REDACTED]", "content-type": "application/json", ...headers }, body: input === undefined ? undefined : JSON.stringify(input) })
  return { root, project, host, store, request }
}
afterEach(async () => {
  for (const item of fixtures.splice(0)) { await item.app.server.stop(true); item.store.close(); rmSync(item.root, { recursive: true, force: true }) }
})
test("workspace HTTP edits preserve BOM and CRLF, refresh source graph, and retain privacy and scope", async () => {
  const { project, request } = fixture(), path = join(project, "说明.md")
  writeFileSync(path, Buffer.from("\uFEFF第一行\r\n最初资料\r\n"))
  const roots = await (await request("/workspace/roots")).json()
  expect(roots.error).toBeNull()
  expect(roots.roots[0].id).toBe(roots.defaultRootId)
  const rootId = roots.defaultRootId
  const listing = await (await request(`/workspace/list?rootId=${rootId}`)).json()
  expect(listing.entries).toHaveLength(1)
  expect(listing.entries[0].editable).toBe(true)
  const imported = await (await request("/workspace/import", { rootId, path: "说明.md", scope: "project-a", private: true })).json()
  expect(imported.private).toBe(true)
  const old = await (await request(`/workspace/file?${new URLSearchParams({ rootId, path: "说明.md" })}`)).json()
  expect(old.bom).toBe(true)
  expect(old.lineEnding).toBe("crlf")
  const response = await request("/workspace/file", { rootId, path: "说明.md", expectedSha256: old.sha256, text: "第一行\n修改后的资料\n" }, "PUT")
  expect(response.status).toBe(200)
  const saved = await response.json()
  expect(readFileSync(path, "utf8")).toBe("\uFEFF第一行\r\n修改后的资料\r\n")
  expect(readFileSync(saved.backupPath, "utf8")).toBe("\uFEFF第一行\r\n最初资料\r\n")
  expect(saved.knowledge).toEqual({ refreshed: 1, warnings: [] })
  const docs = await (await request("/knowledge")).json()
  expect(docs[0].id).toBe(imported.id)
  expect(docs[0].scope).toBe("project-a")
  expect(docs[0].private).toBe(true)
  expect(docs[0].contentHash).toBe(saved.sha256)
  expect(docs[0].revision).toBe(imported.revision + 1)
  expect((await (await request("/graph?scope=project-a")).json()).nodes).toHaveLength(0)
  const graph = await (await request("/graph?scope=project-a&private=true")).json()
  expect(graph.nodes.some((node: { id: string }) => node.id === `document:${imported.id}`)).toBe(true)
})
test("workspace HTTP rejects stale saves, protected roots, traversal and unauthenticated requests", async () => {
  const { project, host, request } = fixture()
  writeFileSync(join(project, "a.md"), "first")
  const { defaultRootId: rootId } = await (await request("/workspace/roots")).json()
  const old = await (await request(`/workspace/file?rootId=${rootId}&path=a.md`)).json()
  writeFileSync(join(project, "a.md"), "external-change")
  expect((await request("/workspace/file", { rootId, path: "a.md", expectedSha256: old.sha256, text: "editor" }, "PUT")).status).toBe(409)
  expect(readFileSync(join(project, "a.md"), "utf8")).toBe("external-change")
  expect((await request("/workspace/roots", { directory: host })).status).toBe(403)
  expect((await request(`/workspace/file?rootId=${rootId}&path=../host/soul.db`)).status).toBe(403)
  expect((await request("/workspace/roots", undefined, "GET", { authorization: "[REDACTED]" })).status).toBe(401)
  expect((await request("/workspace/roots", undefined, "GET", { origin: "https://external.invalid" })).status).toBe(403)
  expect((await request("/workspace/import", { rootId, path: "a.md", scope: "project" })).status).toBe(400)
})
test("workspace HTTP accepts large text and empty edits without relaxing normal API limits", async () => {
  const { project, request } = fixture()
  writeFileSync(join(project, "large.md"), "initial")
  const { defaultRootId: rootId } = await (await request("/workspace/roots")).json()
  const file = await (await request(`/workspace/file?rootId=${rootId}&path=large.md`)).json()
  const content = "中文正文\n".repeat(25000)
  const response = await request("/workspace/file", { rootId, path: "large.md", expectedSha256: file.sha256, text: content }, "PUT")
  expect(response.status).toBe(200)
  const saved = await response.json()
  expect(readFileSync(join(project, "large.md"), "utf8")).toBe(content)
  const empty = await request("/workspace/file", { rootId, path: "large.md", expectedSha256: saved.sha256, text: "" }, "PUT")
  expect(empty.status).toBe(200)
  expect(readFileSync(join(project, "large.md"))).toHaveLength(0)
  expect((await request("/memories", { key: "huge", kind: "fact", text: "x".repeat(210000) })).status).toBe(400)
})
import { mkdir } from "node:fs/promises"
import { join, resolve } from "node:path"
import { inspectRelease, type ReleaseValidationReport, type ReleaseTestEvidence } from "../src/releases"
import { PRODUCT_VERSION } from "../src/contracts"
import { sourceHash } from "./source-hash"

const root = resolve(import.meta.dir, "..")
const candidate = resolve(process.argv[2] ?? join(root, "dist", `xingyao-${PRODUCT_VERSION}`))
const inspected = await inspectRelease(candidate)
const buildMetadata = await Bun.file(join(candidate, "release.json")).json() as { sourceHash?: string }
if (buildMetadata.sourceHash !== await sourceHash(root)) throw new Error("当前源码与候选编译来源不一致，请先重新构建")
const reports = join(root, "reports")
await mkdir(reports, { recursive: true })
const stamp = new Date().toISOString().replace(/[:.]/g, "-")
const executable = join(candidate, "opencode.exe")
const startedAt = Date.now()
const typecheck = Bun.spawn([process.execPath, "run", "typecheck"], { cwd: root, stdout: "pipe", stderr: "pipe" })
const types = await Promise.all([new Response(typecheck.stdout).text(), new Response(typecheck.stderr).text(), typecheck.exited])
await Bun.write(join(reports, `${stamp}-typecheck.txt`), types[0] + types[1])
if (types[2] !== 0) throw new Error("类型检查未通过")
const test = Bun.spawn([process.execPath, "test", "test"], { cwd: root, env: { ...process.env, XINGYAO_TEST_OPENCODE: executable }, stdout: "pipe", stderr: "pipe" })
const results = await Promise.all([new Response(test.stdout).text(), new Response(test.stderr).text(), test.exited])
const output = results[0] + results[1]
const logPath = join(reports, `${stamp}-tests.txt`)
await Bun.write(logPath, output)
const clean = output.replace(/\x1b\[[0-9;]*m/g, "")
if (results[2] !== 0 || /[1-9]\d* (?:skip|todo|fail)\b/.test(clean)) throw new Error(`发行测试失败或有未执行项，详见 ${logPath}`)
for (const required of ["real engine and loopback model", "real shell outcomes", "HTTP evidence", "startup decides the clean old host branch before migration", "product-integration", "compiled Windows product", "portable", "recovery"]) if (!clean.includes(required)) throw new Error(`缺少发行验收证据：${required}`)
// New workbench releases must exercise the actual compiled graph UI. The
// isolated browser fixture never reads or modifies the installed identity.
const browser = Bun.spawn([process.execPath, "run", "script/graph-browser-check.mjs", join(candidate, "xingyao.exe")], { cwd: root, stdout: "pipe", stderr: "pipe" })
const browserResult = await Promise.all([new Response(browser.stdout).text(), new Response(browser.stderr).text(), browser.exited])
await Bun.write(join(reports, `${stamp}-browser.txt`), browserResult[0] + browserResult[1])
if (browserResult[2] !== 0) throw new Error(`图谱浏览器验收失败，详见 ${join(reports, `${stamp}-browser.txt`)}`)
const browserReportPath = join(reports, `graph-browser-${PRODUCT_VERSION}.json`)
const browserReport = await Bun.file(browserReportPath).json() as { version?: string; executableSha256?: string; result?: string }
if (browserReport.result !== "passed" || browserReport.version !== inspected.manifest.version || browserReport.executableSha256 !== inspected.manifest.files["xingyao.exe"]) throw new Error("图谱浏览器报告未绑定当前编译制品")
const rechecked = await inspectRelease(candidate)
if (rechecked.manifestHash !== inspected.manifestHash) throw new Error("验收过程中候选制品发生变化")
if (buildMetadata.sourceHash !== await sourceHash(root)) throw new Error("验收过程中产品源码发生变化")
const finishedAt = Date.now()
const evidence = (names: string[]): ReleaseTestEvidence => ({ passed: true, execution: "real", startedAt, finishedAt, evidence: [logPath, ...names] })
const report: ReleaseValidationReport = { manifestHash: inspected.manifestHash, outcome: "passed", tests: {
  backendContract: evidence(["test/adapter.test.ts", "test/engine.test.ts", "test/real-engine.test.ts"]),
  restore: evidence(["test/checkpoint.test.ts", "test/engine-backup.test.ts", "test/recovery.test.ts", "test/startup-migration.test.ts", "test/compiled.test.ts"]),
  soulIntegration: evidence(["test/product-integration.test.ts", "test/tool-evidence-api.test.ts", "test/source-revisions.test.ts", "test/compiled.test.ts", browserReportPath, join(reports, `${stamp}-browser.txt`)]),
} }
await Bun.write(join(candidate, "release-validation.json"), JSON.stringify(report, null, 2))
console.log(JSON.stringify({ candidate, manifestHash: inspected.manifestHash, tests: clean.match(/\d+ pass\s+\d+ fail/)?.[0] ?? "passed", logPath, report: join(candidate, "release-validation.json") }, null, 2))

"}}

